const taxes = ($input.first().json || {}).taxes || [];
function scoreVAT(t) {
  const n = String(t.tax_name || '').toLowerCase();
  let s = 0;
  if (n.includes('withhold') || n.includes('wht') || n.includes('tds')) s -= 5;
  if (n.includes('vat')) s += 4;
  if (Number(t.tax_percentage) === 7.5) s += 3;
  if (Number(t.tax_percentage) > 0) s += 1;
  return s;
}
const ranked = taxes.slice().sort((a, b) => scoreVAT(b) - scoreVAT(a));
const vat = p.is_taxable ? (ranked[0] && scoreVAT(ranked[0]) > 0 ? ranked[0] : null) : null;
return [{ json: {
  ...p,
  taxes,
  tax_id: vat ? String(vat.tax_id) : '',
  tax_name: vat ? String(vat.tax_name) : '',
  tax_percentage: vat ? Number(vat.tax_percentage) : 0
} }];

function money(n) {
